const sketch = (p5obj:any) => {
    p5obj.setup = () => {
//髱呈｢・ｳ｢縺ｨ縺・≧蜥梧氛繝代ち繝ｼ繝ｳ縺ｧ縺吶よｳ｢讓｡讒倥・蜴壹∩繧・､ｧ縺阪＆縺ｪ縺ｩ驕ｩ螳懷､画峩蜿ｯ閭ｽ
p5obj.createCanvas(500, 500);
p5obj.ellipseMode(p5obj.CORNER);
p5obj.strokeWeight(5);
var r = 45; //豕｢讓｡讒倥・蜊雁ｾ・ＴtrokeWeight縺ｨ荳邱偵↓隱ｿ謨ｴ縺吶ｋ縺ｨ蜷・
var d = 0.55; //蜀・→逵滉ｸ九・蜀・→縺ｮ髢馴囈縲Ｅ=1縺ｮ縺ｨ縺・r蛻・
var n = 5; //豕｢縺ｮ螻､縺系螻､縺ｫ縺ｪ繧・
for (var k=0; (k-1)*r*d<=500+r; k++)
{
  //邵ｦ蟷・00繧貞沂繧√◆繧峨◎繧御ｻ･荳翫ｒ謠冗判縺励↑縺・ｈ縺・ｪｿ謨ｴ
  for (var j=0; (j-1)*2*r<=500; j++)
  { //讓ｪ蟷・ｂ蜷梧ｧ倥・
    for (var i=n; i>=1; i--)
    {
      p5obj.stroke(58, 143-k, 183-k); //霆ｽ縺・げ繝ｩ繝・・繧ｷ繝ｧ繝ｳ
      p5obj.ellipse(r-r*i/n + j*2*r -k%2*r,
        //-k%2*r縺ｧ荳谿ｵ縺壹▽蝎帙∩蜷医≧繧医≧縺ｫ縺壹ｉ縺・
        -r*i/n + k*r*d,
        i*2*r/n,
        i*2*r/n);
    }
  }
}

  };
};

export default sketch;
