const sketch = (p5obj:any) => {
/**
 ステンドグラス模様の描画
 
 - fillとstrokeを分けて描画
 - 窓の模様の中に窓を再帰的に描画
 */

// ガラス部分の照明.
const BRIGHTNESS_INTENSITY: number[] = [ 0.9, 0.8 ];
const BRIGHTNESS_FILTER_POS: number[][] = [[  250, 300 ],[ 600, 650  ]];
const BRIGHTNESS_FILTER_SIZE: number[][] = [[  300, 300 ],
  [ 600, 500  ]];
// window common
const FILL_SET_COMMON: number[][] = [[ 4, 2, 5, 3, 2, 1, 3, 2],[4, 0, 5, 2, 0, 5, 2, 4 ]];
// triangle strip
const FILL_SET_TRIANGLE_STRIP: number[][] = [[ 2, 5],[4, 6 ]];
// circle clover
const FILL_SET_CIRCLE_CLOVER: number[][] = [[ 0, 2, 0, 3, 4, 1, 1, 5, 1],[5, 0, 1, 5, 2, 1, 0, 0, 0 ]];

// circle fan
const FILL_SET_CIRCLE_FAN: number[][] = [[ 4, 6, 5, 2],[4, 3, 5, 5 ]];

// window fan
const FILL_SET_WINDOW_FAN: number[][] = [[ 0, 4],[6, 5 ]];

// モジュール毎のストローク.
const STROKE_SET_COMMON: number[] = [ 3, 0, 0, 0, 0, 0, 0, 0, 0, 2, 3 ];
const STROKE_SET_TRIANGLE_STRIP: number[] = [ 2, 0 ];
const STROKE_SET_CIRCLE_CLOVER: number[] = [ 3, 0, 0, 0, 0, 0, 0, 2 ];
const STROKE_SET_CIRCLE_FAN: number[] = [ 0 ];
const STROKE_SET_WINDOW_FAN: number[] = [ 0, 0 ];

// 調色.
const COLOR_TONE: number[][] = [[  80, 90, 10, 16, 8, 12 ], // Magenta  :0
 [ 52, 60, 10, 16, 10, 12 ], // Cyan     :1
 [ 28, 36, 10, 16, 8, 12], // Green    :2
 [ 15, 16, 10, 16, 8, 12], // Yellow   :3
 [ -4, 4, 10, 16, 8, 12], // Red      :4
 [ 65, 66, 12, 16, 8, 12], // Blue     :5
 [ 100, 100, 0, 2, 13, 15 ]];  // White    :6

// ストローク太さの種類.
const STROKE_WEIGHT: number[] = [  8, 10, 14, 24 ];

const WINDOW_DEFAULT_SIZE: number[] = [  500, 850  ];
const TRIANGLE_STRIP_VERTEX: number[][][] = [[  [0, 0.15], [-0.14, 0.08], [-0.21, 0.17]   ],
  [ [-0.21, 0.17], [-0.36, 0.25], [-0.23, 0.29] ],
  [ [-0.36, 0.25], [-0.23, 0.29], [-0.38, 0.34]  ],
  [ [-0.38, 0.34], [-0.46, 0.42], [-0.30, 0.42]  ],
  [ [-0.46, 0.45], [-0.34, 0.45], [-0.40, 0.56]  ],
  [ [-0.40, 0.56], [-0.45, 0.68], [-0.34, 0.68]   ]];

p5obj.setup = () => 
{
  p5obj.createCanvas(1000, 1000);
  p5obj.colorMode(p5obj.HSB, 100, 16, 16, 1.0 );
  p5obj.background(10, 6, 2);

  // fill描画
  drawWindow( 0.25*p5obj.width, 0.07*p5obj.height, 1, 0, 2 );
  drawWindow( 0.75*p5obj.width, 0.07*p5obj.height, 1, 1, 2 );

  // フィルター
  brightnessFilter();

  // stroke描画
  drawWindow( 0.25*p5obj.width, 0.07*p5obj.height, 1, -1, 3 );
  drawWindow( 0.75*p5obj.width, 0.07*p5obj.height, 1, -1, 3 );
}
const drawWindow = (fPosX: number, fPosY: number, fScale: number, iColorSet: number, iLevel: number) => {
  p5obj.push();
  p5obj.translate(fPosX, fPosY);
  p5obj.scale( fScale );

  // 共通部分
  drawWindowCommon( 0, 0, WINDOW_DEFAULT_SIZE[0], WINDOW_DEFAULT_SIZE[1], iColorSet );

  // 再帰部分(fill)
  if ( iLevel > 0 )
  {
    drawWindow( -0.25*WINDOW_DEFAULT_SIZE[0], 0.73*WINDOW_DEFAULT_SIZE[1], 0.28, iColorSet, iLevel-1 );//再帰呼び出し
    drawWindow( +0.25*WINDOW_DEFAULT_SIZE[0], 0.73*WINDOW_DEFAULT_SIZE[1], 0.28, iColorSet, iLevel-2 );//再帰呼び出し
  } else
  {
    drawWindowFan( -0.25*WINDOW_DEFAULT_SIZE[0], 0.65*WINDOW_DEFAULT_SIZE[1], 0.48*WINDOW_DEFAULT_SIZE[0], 0.5*WINDOW_DEFAULT_SIZE[1], iColorSet );
    drawWindowFan( +0.25*WINDOW_DEFAULT_SIZE[0], 0.65*WINDOW_DEFAULT_SIZE[1], 0.48*WINDOW_DEFAULT_SIZE[0], 0.5*WINDOW_DEFAULT_SIZE[1], iColorSet );
  }

  p5obj.pop();
}
const drawWindowCommon = (fPosX: number, fPosY: number, fWidth: number, fHeight: number, iColorSet: number) => {
  p5obj.push();
  
  let iCurrentDrawIdx: number = 0;
  setFillAndStroke( iColorSet );
  
  // 窓枠
  iCurrentDrawIdx = fillOrStroke( iColorSet, iCurrentDrawIdx, 0 );
  drawWindowFrame( fPosX, fPosY, fWidth, fHeight, 1.0, iColorSet );
  
  // 中心の三つの円
  fillOrStroke( iColorSet, iCurrentDrawIdx, 0 );
  p5obj.circle( fPosX, fPosY+0.765*fHeight, 0.09*fWidth );
  fillOrStroke( iColorSet, iCurrentDrawIdx, 0 );
  p5obj.circle( fPosX+0.05*fWidth, fPosY+0.715*fHeight, 0.09*fWidth );
  iCurrentDrawIdx = fillOrStroke( iColorSet, iCurrentDrawIdx, 0 );
  p5obj.circle( fPosX-0.05*fWidth, fPosY+0.715*fHeight, 0.09*fWidth );
  // 左右の装飾
  fillOrStroke( iColorSet, iCurrentDrawIdx, 0 );
  p5obj.circle( fPosX-0.4*fWidth, fPosY+0.645*fHeight, 0.18*fWidth );
  iCurrentDrawIdx = fillOrStroke( iColorSet, iCurrentDrawIdx, 0 );
  p5obj.circle( fPosX+0.4*fWidth, fPosY+0.645*fHeight, 0.18*fWidth );
  // 左右の花
  fillOrStroke( iColorSet, iCurrentDrawIdx, 0 );
  draw4Clover( fPosX-0.4*fWidth, fPosY+0.645*fHeight, 0.135*fWidth, 0, iColorSet );
  iCurrentDrawIdx = fillOrStroke( iColorSet, iCurrentDrawIdx, 0 );
  draw4Clover( fPosX+0.4*fWidth, fPosY+0.645*fHeight, 0.135*fWidth, 0, iColorSet );
  // 左右の４つの花
  fillOrStroke( iColorSet, iCurrentDrawIdx, 0 );
  draw4Clover( fPosX-0.45*fWidth, fPosY+0.57*fHeight, 0.075*fWidth, 0, iColorSet );
  fillOrStroke( iColorSet, iCurrentDrawIdx, 0 );
  draw4Clover( fPosX+0.45*fWidth, fPosY+0.57*fHeight, 0.075*fWidth, 0, iColorSet );
  fillOrStroke( iColorSet, iCurrentDrawIdx, 0 );
  draw4Clover( fPosX-0.45*fWidth, fPosY+0.725*fHeight, 0.075*fWidth, 0, iColorSet );
  iCurrentDrawIdx = fillOrStroke( iColorSet, iCurrentDrawIdx, 0 );
  draw4Clover( fPosX+0.45*fWidth, fPosY+0.725*fHeight, 0.075*fWidth, 0, iColorSet );
  // 上部の装飾
  iCurrentDrawIdx = fillOrStroke( iColorSet, iCurrentDrawIdx, 0 );
  draw4Clover( fPosX-0.12*fWidth, fPosY+0.095*fHeight, 0.07*fWidth, 0, iColorSet );
  draw4Clover( fPosX+0.12*fWidth, fPosY+0.095*fHeight, 0.07*fWidth, 0, iColorSet );
  // 上部中心
  iCurrentDrawIdx = fillOrStroke( iColorSet, iCurrentDrawIdx, 0 );
  p5obj.circle( fPosX, fPosY+0.066*fHeight, 0.17*fWidth );
  iCurrentDrawIdx = fillOrStroke( iColorSet, iCurrentDrawIdx, 0 );
  draw4Clover( fPosX, fPosY+0.067*fHeight, 0.12*fWidth, 0, iColorSet );
  if ( iColorSet<0 )
  {
    iCurrentDrawIdx = fillOrStroke( iColorSet, iCurrentDrawIdx, 0 );
    p5obj.line(fPosX-0.03*fWidth, fPosY+0.045*fHeight, fPosX+0.03*fWidth, fPosY+0.085*fHeight);
    p5obj.line(fPosX-0.03*fWidth, fPosY+0.085*fHeight, fPosX+0.03*fWidth, fPosY+0.045*fHeight);
  }
  
  // 三角形ストリップ枠.
  drawTriangleStrip( -0.25*fWidth, 0.65*fHeight, 0.48*fWidth, 0.5*fHeight, iColorSet );
  drawTriangleStrip( 0.25*fWidth, 0.65*fHeight, 0.48*fWidth, 0.5*fHeight, iColorSet );
  
  // 大きな円部分
  drawCircleClover( fPosX, fPosY + 0.4*fHeight, 0.94*fWidth, iColorSet );
  
  // その他フレーム
  if ( iColorSet<0 )
  {
    iCurrentDrawIdx = fillOrStroke( iColorSet, iCurrentDrawIdx, 0 );
    p5obj.line( fPosX-0.5*fWidth, fPosY+0.51*fHeight, fPosX+0.5*fWidth, fPosY+0.51*fHeight);
    iCurrentDrawIdx = fillOrStroke( iColorSet, iCurrentDrawIdx, 0 );
    p5obj.line( fPosX-0.5*fWidth, fPosY+0.87*fHeight, fPosX+0.5*fWidth, fPosY+0.87*fHeight);
  }
  p5obj.pop();
}
const drawTriangleStrip = (fPosX: number, fPosY: number, fWidth: number, fHeight: number, iColorSet: number) => {
  p5obj.push();

  let iCurrentDrawIdx: number = 0;
  setFillAndStroke( iColorSet );

  // ストリップ枠
  iCurrentDrawIdx = fillOrStroke( iColorSet, iCurrentDrawIdx, 1 );
  drawWindowFrame( fPosX, fPosY, fWidth, fHeight, 0.7, iColorSet );

  // 四辺形模様
  iCurrentDrawIdx = fillOrStroke( iColorSet, iCurrentDrawIdx, 1 );
  p5obj.quad(fPosX, fPosY, fPosX-0.15*fWidth, fPosY+0.08*fHeight, fPosX, fPosY+0.15*fHeight, fPosX+0.15*fWidth, fPosY+0.08*fHeight );
  
  //TRIANGLE_STRIP
  for ( let iSymmetric: number = 0; iSymmetric<2; iSymmetric++ )
  {
    let fXSymmetric: number = 1;
    if ( iSymmetric%2==1 )
    {
      fXSymmetric = -1;
    }
    for ( let iTriangleIdx: number = 0; iTriangleIdx < TRIANGLE_STRIP_VERTEX.length; iTriangleIdx++ )
    {
      p5obj.triangle( fPosX+fXSymmetric*TRIANGLE_STRIP_VERTEX[iTriangleIdx][0][0]*fWidth,
        fPosY+TRIANGLE_STRIP_VERTEX[iTriangleIdx][0][1]*fHeight,
        fPosX+fXSymmetric*TRIANGLE_STRIP_VERTEX[iTriangleIdx][1][0]*fWidth,
        fPosY+TRIANGLE_STRIP_VERTEX[iTriangleIdx][1][1]*fHeight,
        fPosX+fXSymmetric*TRIANGLE_STRIP_VERTEX[iTriangleIdx][2][0]*fWidth,
        fPosY+TRIANGLE_STRIP_VERTEX[iTriangleIdx][2][1]*fHeight );
    }
  }
  p5obj.pop();
}
const drawWindowFan = (fPosX: number, fPosY: number, fWidth: number, fHeight: number, iColorSet: number) => {
  p5obj.push();
  
  let iCurrentDrawIdx: number = 0;
  setFillAndStroke( iColorSet );
  
  // 内
  iCurrentDrawIdx = fillOrStroke( iColorSet, iCurrentDrawIdx, 4 );
  drawWindowFrame( fPosX, fPosY+0.15*fHeight, 0.6*fWidth, 0.58*fHeight, 0.95, iColorSet );

  // 中央のアンブレラ.
  drawCircleFan( fPosX, fPosY+0.31*fHeight, 0.38*fWidth, iColorSet );
  drawCircleFan( fPosX, fPosY+0.57*fHeight, 0.38*fWidth, iColorSet );

  // 赤の長方形
  iCurrentDrawIdx = fillOrStroke( iColorSet, iCurrentDrawIdx, 4 );
  p5obj.rect( fPosX-0.3*fWidth, fPosY+0.46*fHeight, 0.1*fWidth, 0.11*fHeight );
  p5obj.rect( fPosX+0.2*fWidth, fPosY+0.46*fHeight, 0.1*fWidth, 0.11*fHeight );
  p5obj.rect( fPosX-0.3*fWidth, fPosY+0.58*fHeight, 0.1*fWidth, 0.11*fHeight );
  p5obj.rect( fPosX+0.2*fWidth, fPosY+0.58*fHeight, 0.1*fWidth, 0.11*fHeight );

  p5obj.pop();
}
const drawCircleClover = (fPosX: number, fPosY: number, fDiameter: number, iColorSet: number) => {
  p5obj.push();
  p5obj.translate( fPosX, fPosY );

  let iCurrentDrawIdx: number = 0;
  setFillAndStroke( iColorSet );

  // bg circle
  if ( iColorSet<0 )
  {
    iCurrentDrawIdx = fillOrStroke( iColorSet, iCurrentDrawIdx, 2 );
  } else
  {
    for ( let iRotate: number = 15; iRotate<375; iRotate+=30 )
    {
      fillOrStroke( iColorSet, iCurrentDrawIdx, 2 );
      p5obj.arc( 0, 0, fDiameter, fDiameter, p5obj.radians(iRotate), p5obj.radians(iRotate+30), p5obj.PIE  );
    }
    iCurrentDrawIdx++;
  }
  p5obj.circle( 0, 0, fDiameter );
  
  // bg middle circle
  if ( iColorSet>=0 )
  {
    for ( let iRotate: number = 15; iRotate<375; iRotate+=30 )
    {
      fillOrStroke( iColorSet, iCurrentDrawIdx, 2 );
      p5obj.arc( 0, 0, 0.75*fDiameter, 0.75*fDiameter, p5obj.radians(iRotate), p5obj.radians(iRotate+30), p5obj.PIE  );
    }
    iCurrentDrawIdx++;
  }
  
  // bg small circle
  if ( iColorSet<0 )
  {
    iCurrentDrawIdx = fillOrStroke( iColorSet, iCurrentDrawIdx, 2 );
    p5obj.circle( 0, 0, 0.39*fDiameter );
  }
  else
  {
    for ( let iRotate: number = 15; iRotate<375; iRotate+=30 )
    {
      fillOrStroke( iColorSet, iCurrentDrawIdx, 2 );
      p5obj.arc( 0, 0, 0.39*fDiameter, 0.39*fDiameter, p5obj.radians(iRotate), p5obj.radians(iRotate+30), p5obj.PIE  );
    }
    iCurrentDrawIdx++;
  }
  iCurrentDrawIdx = fillOrStroke( iColorSet, iCurrentDrawIdx, 2 );
  p5obj.circle( 0, 0, 0.28*fDiameter );
  
  // center clover
  iCurrentDrawIdx = fillOrStroke( iColorSet, iCurrentDrawIdx, 2 );
  draw4Clover(  0, 0, 0.2*fDiameter, 15, iColorSet );
  iCurrentDrawIdx = fillOrStroke( iColorSet, iCurrentDrawIdx, 2 );
  p5obj.circle(  0, 0, 0.1*fDiameter );
  iCurrentDrawIdx = fillOrStroke( iColorSet, iCurrentDrawIdx, 2 );
  p5obj.circle( 0, 0, 0.13*fDiameter );
  
  // Clover
  let fCloverDiameter: number = fDiameter / 6.0;
  for ( let iRotate: number = 15; iRotate<375; iRotate+=30 )
  {
    if ( iColorSet<0 )
    {
      fillOrStroke( iColorSet, iCurrentDrawIdx, 2 );
    } else
    {
      if ( p5obj.random(100)<30 )
      {
        fillOrStroke( iColorSet, iCurrentDrawIdx, 2 );
      } else
      {
        fillOrStroke( iColorSet, iCurrentDrawIdx+1, 2 );
      }
    }
    draw4Clover(  0.47*(fDiameter-fCloverDiameter)*p5obj.cos(p5obj.radians(iRotate)),
      0.47*(fDiameter-fCloverDiameter)*p5obj.sin(p5obj.radians(iRotate)),
      fCloverDiameter, iRotate, iColorSet );
  }
  if ( iColorSet<0 )
  {
    iCurrentDrawIdx++;
  } else
  {
    iCurrentDrawIdx += 2;
  }
  
  // radial lines
  if ( iColorSet<0 )
  {
    iCurrentDrawIdx = fillOrStroke( iColorSet, iCurrentDrawIdx, 2 );
    for ( let iRotate: number = 15; iRotate<375; iRotate+=30 )
    {
      p5obj.line( (0.15*fDiameter)*p5obj.cos(p5obj.radians(iRotate)),
        (0.15*fDiameter)*p5obj.sin(p5obj.radians(iRotate)),
        (0.29*fDiameter)*p5obj.cos(p5obj.radians(iRotate)),
        (0.29*fDiameter)*p5obj.sin(p5obj.radians(iRotate)) );
    }
  }
  p5obj.pop();
}
const drawCircleFan = (fPosX: number, fPosY: number, fDiameter: number, iColorSet: number) => {
  p5obj.push();
  p5obj.translate( fPosX, fPosY );
  
  let iCurrentDrawIdx: number = 0;
  setFillAndStroke( iColorSet );

  if ( iColorSet<0 )
  {
    iCurrentDrawIdx = fillOrStroke( iColorSet, iCurrentDrawIdx, 3 );
    for ( let fRotate: number = 0; fRotate<360; fRotate+=45 )
    {
      let fLineEndX: number = 0.5*fDiameter*p5obj.cos(p5obj.radians(fRotate-22.5));
      let fLineEndY: number = 0.5*fDiameter*p5obj.sin(p5obj.radians(fRotate-22.5));
      p5obj.line( 0.3*fLineEndX, 0.3*fLineEndY, fLineEndX, fLineEndY );
      if ( fRotate%90 == 0 )
      {
        let fVertex1X: number = 0.35*fDiameter*p5obj.cos(p5obj.radians(fRotate-22.5));
        let fVertex1Y: number = 0.35*fDiameter*p5obj.sin(p5obj.radians(fRotate-22.5));
        let fVertex2X: number = 0.5*fDiameter*p5obj.cos(p5obj.radians(fRotate+22.5));
        let fVertex2Y: number = 0.5*fDiameter*p5obj.sin(p5obj.radians(fRotate+22.5));
        p5obj.line( fVertex1X, fVertex1Y, fVertex2X, fVertex2Y );
      }
    }
    p5obj.circle( 0, 0, 0.3*fDiameter );
    p5obj.circle( 0, 0, fDiameter );
  } else
  {
    for ( let fRotate: number = 0; fRotate<360; fRotate+=90 )
    {
      fillOrStroke( iColorSet, iCurrentDrawIdx, 3 );
      p5obj.arc( 0, 0, fDiameter, fDiameter, p5obj.radians(fRotate-22.5), p5obj.radians(fRotate+22.5), p5obj.PIE );
      fillOrStroke( iColorSet, iCurrentDrawIdx+1, 3 );
      p5obj.arc( 0, 0, fDiameter, fDiameter, p5obj.radians(fRotate+22.5), p5obj.radians(fRotate+67.5), p5obj.PIE );
      fillOrStroke( iColorSet, iCurrentDrawIdx+2, 3 );
      let fVertex0X: number = 0.5*fDiameter*p5obj.cos(p5obj.radians(fRotate-22.5));
      let fVertex0Y: number = 0.5*fDiameter*p5obj.sin(p5obj.radians(fRotate-22.5));
      let fVertex1X: number = 0.35*fDiameter*p5obj.cos(p5obj.radians(fRotate-22.5));
      let fVertex1Y: number = 0.35*fDiameter*p5obj.sin(p5obj.radians(fRotate-22.5));
      let fVertex2X: number = 0.5*fDiameter*p5obj.cos(p5obj.radians(fRotate+22.5));
      let fVertex2Y: number = 0.5*fDiameter*p5obj.sin(p5obj.radians(fRotate+22.5));
      p5obj.triangle( fVertex0X, fVertex0Y, fVertex1X, fVertex1Y, fVertex2X, fVertex2Y );
    }
    iCurrentDrawIdx+=3;
    iCurrentDrawIdx = fillOrStroke( iColorSet, iCurrentDrawIdx, 3 );
    p5obj.circle( 0, 0, 0.3*fDiameter );
  }

  p5obj.pop();
}
const draw4Clover = (fPosX: number, fPosY: number, fDiameter: number, fAngle: number, iColorSet: number) => {
  p5obj.push();
  p5obj.translate(fPosX, fPosY);
  p5obj.rotate(p5obj.radians(fAngle));

  setFillAndStroke( iColorSet );

  if ( iColorSet<0 )
  {
    p5obj.strokeCap(p5obj.PROJECT);
    for ( let iRotate: number = 0; iRotate<360; iRotate+=90 )
    {
      p5obj.rotate(p5obj.radians(iRotate));
      p5obj.arc( fDiameter/3.4, 0, fDiameter/1.8, fDiameter/1.8, p5obj.radians(-90), p5obj.radians(+90) );
    }
    p5obj.strokeCap(p5obj.ROUND);
  } else
  {
    for ( let iRotate: number = 0; iRotate<360; iRotate+=90 )
    {
      p5obj.rotate(p5obj.radians(iRotate));
      p5obj.arc( fDiameter/3.4, 0, fDiameter/1.8, fDiameter/1.8, p5obj.radians(-90), p5obj.radians(+90) );
    }
    p5obj.circle( 0, -0, 0.94*fDiameter );
  }
  p5obj.pop();
}
const drawWindowFrame = (fPosX: number, fPosY: number, fWidth: number, fHeight: number, fBaseRatio: number, iColorSet: number) => {
  p5obj.push();
  p5obj.translate(fPosX, fPosY);
  
  setFillAndStroke( iColorSet );
  
  // 窓枠
  p5obj.curve( 0.7*fWidth, 0, 0, 0, -0.49*fWidth, 0.42*fHeight,-0.15*fWidth, 1.0*fHeight );
  p5obj.curve(-0.4*fWidth, 0,-0.49*fWidth, 0.42*fHeight, -0.50*fWidth, fHeight*fBaseRatio,-0.50*fWidth, fHeight*fBaseRatio );
  p5obj.curve( -0.7*fWidth, 0, 0, 0, 0.49*fWidth, 0.42*fHeight, 0.15*fWidth, 1.0*fHeight );
  p5obj.curve(0.4*fWidth, 0, 0.49*fWidth, 0.42*fHeight, 0.50*fWidth, fHeight*fBaseRatio, 0.50*fWidth, fHeight*fBaseRatio );
  p5obj.line(-0.50*fWidth, fHeight*fBaseRatio, 0.50*fWidth, fHeight*fBaseRatio);
  
  if ( iColorSet>=0 )
  {
    p5obj.noStroke();
    p5obj.beginShape();
    p5obj.vertex( 0, 0 );
    p5obj.vertex( -0.49*fWidth, 0.42*fHeight );
    p5obj.vertex( -0.50*fWidth, fHeight*fBaseRatio );
    p5obj.vertex( 0.50*fWidth, fHeight*fBaseRatio );
    p5obj.vertex( 0.49*fWidth, 0.42*fHeight );
    p5obj.endShape(p5obj.CLOSE);
  }
  p5obj.pop();
}
const brightnessFilter = () => {
  for ( let iFilterIdx: number = 0; iFilterIdx<BRIGHTNESS_INTENSITY.length; iFilterIdx++ )
  {
    let iCenterX: number = BRIGHTNESS_FILTER_POS[iFilterIdx][0];
    let iCenterY: number = BRIGHTNESS_FILTER_POS[iFilterIdx][1];
    let iWidth: number = BRIGHTNESS_FILTER_SIZE[iFilterIdx][0];
    let iHeight: number = BRIGHTNESS_FILTER_SIZE[iFilterIdx][1];
    let fIntensity: number = BRIGHTNESS_INTENSITY[iFilterIdx];

    p5obj.push();
    p5obj.translate(iCenterX, iCenterY);

    for ( let iPixelY: number = -iHeight/2; iPixelY<iHeight/2; iPixelY++ )
    {
      for ( let iPixelX: number = -iWidth/2; iPixelX<iWidth/2; iPixelX++ )
      {
        // 楕円の方程式
        let fEllipse: number = p5obj.pow(iPixelX/iWidth/2, 2)+p5obj.pow(iPixelY/iHeight/2, 2);
        if ( fEllipse < 1 )
        {
          let fBrightnessAdd: number = fIntensity*(1 - fEllipse);
          p5obj.stroke( 20, 6, 16, fBrightnessAdd );
          p5obj.point( iPixelX, iPixelY );
        }
      }
    }
    p5obj.pop();
  }
}
const fillOrStroke = (iColorSet:number, iCurrentDrawIdx:number, iModuleIdx:number ): number =>
{
  if ( iColorSet < 0 )
  {
    let iStroke: number = 0;
    switch(iModuleIdx)
    {
    case 0:  // window common
      iStroke = STROKE_SET_COMMON[iCurrentDrawIdx];
      break;
    case 1:  // triangle strip
      iStroke = STROKE_SET_TRIANGLE_STRIP[iCurrentDrawIdx];
      break;
    case 2:
      iStroke = STROKE_SET_CIRCLE_CLOVER[iCurrentDrawIdx];
      break;
    case 3:
      iStroke = STROKE_SET_CIRCLE_FAN[iCurrentDrawIdx];
      break;
    case 4:
      iStroke = STROKE_SET_WINDOW_FAN[iCurrentDrawIdx];
      break;
    }
    p5obj.stroke( 10, 6, 2 );
    p5obj.strokeWeight(STROKE_WEIGHT[iStroke]);
    console.log("stroke:"+iStroke+" DrawIdx:"+iCurrentDrawIdx+" Module:"+iModuleIdx);
  } else
  {
    let iColorIdx: number = 0;
    switch(iModuleIdx)
    {
    case 0:  // window common
      iColorIdx = FILL_SET_COMMON[iColorSet][iCurrentDrawIdx];
      break;
    case 1:  // triangle strip
      iColorIdx = FILL_SET_TRIANGLE_STRIP[iColorSet][iCurrentDrawIdx];
      break;
    case 2:
      iColorIdx = FILL_SET_CIRCLE_CLOVER[iColorSet][iCurrentDrawIdx];
      break;
    case 3:
      iColorIdx = FILL_SET_CIRCLE_FAN[iColorSet][iCurrentDrawIdx];
      break;
    case 4:
      iColorIdx = FILL_SET_WINDOW_FAN[iColorSet][iCurrentDrawIdx];
      break;
    }
    p5obj.fill( p5obj.random(COLOR_TONE[iColorIdx][0], COLOR_TONE[iColorIdx][1]),
      p5obj.random(COLOR_TONE[iColorIdx][2], COLOR_TONE[iColorIdx][3]),
      p5obj.random(COLOR_TONE[iColorIdx][4], COLOR_TONE[iColorIdx][5]) );
    console.log("fill:"+iColorIdx+" DrawIdx:"+iCurrentDrawIdx+" Module:"+iModuleIdx);
  }
  return iCurrentDrawIdx+1;
}

  const setFillAndStroke = (iColorSet: number) => {
    if ( iColorSet<0 )
    {
      p5obj.noFill();
    }
    else
    {
      p5obj.noStroke();
    }
  }

};

export default sketch;